'use client';

import { useLayoutEffect, useRef, useState } from 'react';
import { gsap, gsapInit, ScrollTrigger } from '@/lib/animations/gsap';
import PortableText from '@/components/sanity/PortableText';
import ArticleCard, { type ArticleCardData } from '@/components/ui/ArticleCard';
import GridWrapper from '@/components/layout/GridWrapper';
import Section from '@/components/layout/Section';
import FadeUp from '@/components/animations/FadeUp';
import type { PortableTextBlock } from '@portabletext/types';
import type { Insight } from '@/lib/sanity/types';

interface TocItem {
  key: string;
  text: string;
  level: 'h2' | 'h3';
}

function extractToc(blocks: PortableTextBlock[]): TocItem[] {
  if (!blocks) return [];
  return blocks
    .filter((b) => b.style === 'h2' || b.style === 'h3')
    .map((b) => ({
      key: b._key ?? '',
      text: (b.children as { text: string }[]).map((c) => c.text).join(''),
      level: b.style as 'h2' | 'h3',
    }));
}

function formatDate(dateStr: string): string {
  if (!dateStr) return '';
  return new Date(dateStr).toLocaleDateString('en-GB', {
    day: 'numeric',
    month: 'long',
    year: 'numeric',
  });
}

interface ArticleDetailClientProps {
  article: Insight;
  related: Insight[];
}

export default function ArticleDetailClient({ article, related }: ArticleDetailClientProps) {
  const body = (article.body as PortableTextBlock[]) || [];
  const toc = extractToc(body);
  const [activeHeading, setActiveHeading] = useState<string>(toc[0]?.key ?? '');
  const articleRef = useRef<HTMLDivElement>(null);

  // TOC scroll tracking via ScrollTrigger
  useLayoutEffect(() => {
    gsapInit();
    if (!articleRef.current || toc.length === 0) return;

    const ctx = gsap.context(() => {
      toc.forEach(({ key }) => {
        const el = document.getElementById(`heading-${key}`);
        if (!el) return;
        ScrollTrigger.create({
          trigger: el,
          start: 'top 30%',
          end: 'bottom 30%',
          onEnter: () => setActiveHeading(key),
          onEnterBack: () => setActiveHeading(key),
        });
      });
    }, articleRef);

    return () => ctx.revert();
  }, [toc.length]); // eslint-disable-line react-hooks/exhaustive-deps

  const handleShare = async () => {
    const url = window.location.href;
    if (navigator.share) {
      await navigator.share({ title: article.title, url }).catch(() => undefined);
    } else {
      await navigator.clipboard.writeText(url);
      alert('Link copied to clipboard.');
    }
  };

  return (
    <main className="bg-void text-paper">
      {/* ── Article Hero ── */}
      <section className="pb-16 pt-40">
        <GridWrapper>
          <FadeUp>
            <div className="mb-6 flex flex-wrap items-center gap-4">
              <span className="text-label text-threshold">
                {article.category?.title?.toUpperCase() || 'UNCATEGORIZED'}
              </span>
              <span className="text-label text-stone">·</span>
              <span className="text-label text-stone">5 min read</span>
            </div>
          </FadeUp>
          <FadeUp delay={100}>
            <h1 className="mb-8 max-w-3xl text-display-md text-paper">{article.title}</h1>
          </FadeUp>
          <FadeUp delay={200}>
            <div className="flex items-center gap-6 border-t border-border pt-6">
              <div>
                <p className="text-label text-stone">
                  {article.author?.name?.toUpperCase() || 'TDK DESIGN & BUILD'}
                </p>
                <p className="text-body text-stone">{formatDate(article.publishDate || '')}</p>
              </div>
              <button
                type="button"
                onClick={handleShare}
                className="ml-auto text-label text-stone transition-colors duration-fast ease-smooth hover:text-paper"
              >
                SHARE →
              </button>
            </div>
          </FadeUp>
        </GridWrapper>
      </section>

      {/* ── Article Body + TOC ── */}
      <Section>
        <GridWrapper>
          <div className="relative grid gap-16 lg:grid-cols-[1fr_280px]">
            {/* Body */}
            <div ref={articleRef} className="min-w-0">
              <PortableText value={body} />
            </div>

            {/* TOC — sticky sidebar on desktop */}
            {toc.length > 0 && (
              <aside className="hidden lg:block">
                <div className="sticky top-24">
                  <p className="mb-4 text-label text-stone">CONTENTS</p>
                  <nav className="flex flex-col gap-2">
                    {toc.map(({ key, text, level }) => (
                      <a
                        key={key}
                        href={`#heading-${key}`}
                        className={`block text-body transition-colors duration-fast ease-smooth ${
                          level === 'h3' ? 'pl-4' : ''
                        } ${
                          activeHeading === key ? 'text-threshold' : 'text-stone hover:text-paper'
                        }`}
                      >
                        {text}
                      </a>
                    ))}
                  </nav>
                </div>
              </aside>
            )}
          </div>
        </GridWrapper>
      </Section>

      {/* ── Author Bio ── */}
      <Section background="surface">
        <GridWrapper>
          <FadeUp>
            <div className="flex items-start gap-6">
              <div className="h-16 w-16 flex-shrink-0 bg-void" />
              <div>
                <p className="text-label text-paper">
                  {article.author?.name?.toUpperCase() || 'TDK DESIGN & BUILD'}
                </p>
                <p className="mt-2 text-body text-stone">
                  {article.author?.bio ||
                    'TDK Design & Build is a fully integrated architecture, construction, and interior design studio based in Nicosia, Cyprus.'}
                </p>
              </div>
            </div>
          </FadeUp>
        </GridWrapper>
      </Section>

      {/* ── Related Articles ── */}
      {related.length > 0 && (
        <Section>
          <GridWrapper>
            <FadeUp>
              <p className="mb-12 text-label text-stone">MORE INSIGHTS</p>
            </FadeUp>
            <div className="grid gap-12 sm:grid-cols-2">
              {related.map((a, i) => (
                <FadeUp key={a.slug.current} delay={i * 80}>
                  <ArticleCard
                    article={{
                      slug: a.slug.current,
                      title: a.title,
                      category: a.category?.title || 'Uncategorized',
                      excerpt: a.excerpt || '',
                      date: a.publishDate || '',
                      readTime: '5 min read',
                      heroImageId: a.heroImageId || '',
                    }}
                  />
                </FadeUp>
              ))}
            </div>
          </GridWrapper>
        </Section>
      )}
    </main>
  );
}

import type { Metadata } from 'next';
import { notFound } from 'next/navigation';
import ProjectHero from '@/components/sections/project/ProjectHero';
import ProjectOverviewBar from '@/components/sections/project/ProjectOverviewBar';
import ProjectRendersGallery from '@/components/sections/project/ProjectRendersGallery';
import ProjectPhotosGallery from '@/components/sections/project/ProjectPhotosGallery';
import ProjectDescription from '@/components/sections/project/ProjectDescription';
import ProjectSpecs from '@/components/sections/project/ProjectSpecs';
import ProjectProgress from '@/components/sections/project/ProjectProgress';
import ProjectUnitsTable from '@/components/sections/project/ProjectUnitsTable';
import ProjectInterestForm from '@/components/sections/project/ProjectInterestForm';
import ProjectLocation from '@/components/sections/project/ProjectLocation';
import ProjectRelated from '@/components/sections/project/ProjectRelated';
import ProjectCTA from '@/components/sections/project/ProjectCTA';
import { getProjectBySlug, getAllProjects } from '@/lib/sanity/queries';
import type { PortableTextBlock } from '@/lib/sanity/types';

export const revalidate = 60;

interface Props {
  params: Promise<{ locale: string; slug: string }>;
}

export async function generateMetadata({ params }: Props): Promise<Metadata> {
  const { slug } = await params;
  const project = await getProjectBySlug(slug);
  if (!project) return {};

  return {
    title: project.seo?.title || `${project.title} | TDK Design & Build`,
    description: project.seo?.description || project.pullQuote || '',
  };
}

export async function generateStaticParams() {
  const projects = await getAllProjects();
  return projects.map((p) => ({ slug: p.slug.current }));
}

export default async function ProjectDetailPage({ params }: Props) {
  const { slug } = await params;
  const project = await getProjectBySlug(slug);

  if (!project) notFound();

  const showProgress =
    project.ctaType !== 'showcase' &&
    project.status !== 'completed' &&
    project.progressPercent !== undefined;

  const showInterestForm = project.ctaType === 'register-interest';

  // Format overview items dynamically from project fields
  const overviewItems = [
    { label: 'TYPE', value: project.type.charAt(0).toUpperCase() + project.type.slice(1) },
    { label: 'LOCATION', value: project.location },
    {
      label: project.status === 'completed' ? 'COMPLETED' : 'DELIVERY',
      value: String(project.year),
    },
    { label: 'STATUS', value: project.status },
  ];

  // Helper to extract text from PortableText blocks purely for the fallback description body
  const extractText = (blocks: PortableTextBlock[]) => {
    return blocks
      .filter((block) => block._type === 'block' && block.children)
      .map((block) => (block.children as { text: string }[] || []).map((child) => child.text).join(''));
  };

  const descriptionBody = project.description ? extractText(project.description) : [];

  // Map units to the exact component props manually to ensure types always align
  const mappedUnits =
    project.units?.map((u) => ({
      floor: u.floor,
      type: u.unitType,
      area: `${u.sizeM2} m²`,
      price: '—', // Hardcoded for now based on previous UI mock
      status: u.status,
    })) || [];

  // Map related projects
  const relatedProjects = (project.relatedProjectSlugs || []).map((relatedSlug) => ({
    // Note: To display full rich related cards, we'd need GROQ projection for this nested data.
    // For now, based on prompt 6.3 specs, we map to strings.
    // Ideally this query would be expanded in queries.ts, but let's just pass minimal shape.
    slug: relatedSlug,
    title: relatedSlug.toUpperCase(),
    location: '',
    imageId: '',
  }));

  return (
    <main className="bg-void text-paper">
      <ProjectHero
        title={project.title}
        location={project.location}
        status={project.status}
        year={project.year}
        heroImageId={project.heroImageId}
      />

      <ProjectOverviewBar items={overviewItems} />

      <ProjectDescription title={project.pullQuote || 'OVERVIEW'} body={descriptionBody} />

      {project.rendersGallery && project.rendersGallery.images?.length > 0 && (
        <ProjectRendersGallery
          heading={project.rendersGallery.heading}
          images={project.rendersGallery.images}
        />
      )}

      {showProgress && project.progressPercent !== undefined && (
        <ProjectProgress percent={project.progressPercent} label={project.progressLabel ?? ''} />
      )}

      {project.photosGallery && project.photosGallery.images?.length > 0 && (
        <ProjectPhotosGallery
          heading={project.photosGallery.heading}
          images={project.photosGallery.images}
        />
      )}

      {(project.specs?.length ?? 0) > 0 && (
        <ProjectSpecs specs={project.specs?.map((s) => ({ label: s.key, value: s.value })) || []} />
      )}

      {mappedUnits.length > 0 && <ProjectUnitsTable units={mappedUnits} />}

      {showInterestForm && (
        <ProjectInterestForm projectSlug={project.slug.current} projectName={project.title} />
      )}

      {project.mapEmbedUrl && <ProjectLocation address={project.mapEmbedUrl || project.location} />}

      {relatedProjects.length > 0 && <ProjectRelated projects={relatedProjects} />}

      <ProjectCTA ctaType={project.ctaType} />
    </main>
  );
}

import type { Metadata } from 'next';
import { notFound } from 'next/navigation';
import { heroImage } from '@/lib/cloudinary/transforms';
import Section from '@/components/layout/Section';
import GridWrapper from '@/components/layout/GridWrapper';
import TextReveal from '@/components/animations/TextReveal';
import FadeUp from '@/components/animations/FadeUp';
import Accordion from '@/components/ui/Accordion';
import { GhostButton } from '@/components/ui/Button';
import Link from 'next/link';

import { getServiceBySlug, getAllServices } from '@/lib/sanity/queries';
import PortableText from '@/components/sanity/PortableText';
import type { PortableTextBlock } from '@/lib/sanity/types';

export const revalidate = 60;

interface Props {
  params: Promise<{ locale: string; slug: string }>;
}

export async function generateMetadata({ params }: Props): Promise<Metadata> {
  const { slug } = await params;
  const service = await getServiceBySlug(slug);
  if (!service) return {};

  return {
    title: service.seo?.title || `${service.title} | TDK Design & Build`,
    description: service.seo?.description || service.shortDescription || '',
  };
}

export async function generateStaticParams() {
  const services = await getAllServices();
  return services.map((s) => ({ slug: s.slug.current }));
}

export default async function ServiceDetailPage({ params }: Props) {
  const { slug } = await params;
  const service = await getServiceBySlug(slug);
  if (!service) notFound();

  // For related projects, we'll map them similarly to Insights for now
  // Ideally, relatedProjectSlugs should be hydrated byGROQ
  const relatedProjects = (service.relatedProjectSlugs || []).map((relatedSlug) => ({
    slug: relatedSlug,
    title: relatedSlug.toUpperCase(),
    location: '',
    imageId: '',
  }));

  return (
    <main className="bg-void text-paper">
      {/* ── Hero ── */}
      <section className="relative flex min-h-[60vh] items-end pb-24 pt-40">
        <img
          src={heroImage('clients/tdkdb/armonia/exterior/armonia_front_angle_day')}
          alt=""
          aria-hidden="true"
          className="absolute inset-0 h-full w-full object-cover"
          style={{ opacity: 0.3 }}
        />
        <div className="via-void/60 absolute inset-0 bg-gradient-to-t from-void to-transparent" />
        <GridWrapper className="relative z-10">
          <p className="mb-4 text-label text-threshold">SERVICE</p>
          <TextReveal tag="h1" className="max-w-3xl text-display-lg text-paper">
            {service.shortDescription || service.title}
          </TextReveal>
          <p className="mt-4 text-heading font-light text-stone">{service.title}</p>
        </GridWrapper>
      </section>

      {/* ── Description ── */}
      <Section>
        <GridWrapper>
          <div className="grid gap-16 lg:gap-24">
            <div className="flex flex-col gap-6">
              {service.fullDescription ? (
                <PortableText value={service.fullDescription as PortableTextBlock[]} />
              ) : null}
            </div>
          </div>
        </GridWrapper>
      </Section>

      {/* ── Process / Approach ── */}
      {(service.process?.length ?? 0) > 0 && (
        <Section background="surface">
          <GridWrapper>
            <FadeUp>
              <p className="mb-12 text-label text-stone">HOW WE WORK</p>
            </FadeUp>
            <div className="flex flex-col">
              {service.process?.map((step, i) => (
                <FadeUp key={i} delay={i * 80}>
                  <div className="grid grid-cols-[2rem_1fr] gap-8 border-b border-border py-8">
                    <span className="pt-1 text-label text-threshold">0{i + 1}</span>
                    <div className="flex flex-col gap-2">
                      <h3 className="text-body font-semibold text-paper">{step.title}</h3>
                      <p className="text-body text-stone">{step.description}</p>
                    </div>
                  </div>
                </FadeUp>
              ))}
            </div>
          </GridWrapper>
        </Section>
      )}

      {/* ── Related Projects ── */}
      {relatedProjects.length > 0 && (
        <Section>
          <GridWrapper>
            <FadeUp>
              <p className="mb-12 text-label text-stone">RELATED PROJECTS</p>
            </FadeUp>
            <div className="grid gap-8 sm:grid-cols-2">
              {relatedProjects.map((project) => (
                <FadeUp key={project.slug}>
                  <Link
                    href={`/en/projects/${project.slug}`}
                    className="group flex gap-6 border border-border p-6 transition-colors duration-fast ease-smooth hover:border-paper"
                  >
                    <div className="h-24 w-32 flex-shrink-0 overflow-hidden">
                      <img
                        src={heroImage(project.imageId)}
                        alt={project.title}
                        className="h-full w-full object-cover transition-transform duration-medium ease-smooth group-hover:scale-[1.05]"
                      />
                    </div>
                    <div className="flex flex-col justify-center gap-1">
                      <p className="text-label text-paper">{project.title}</p>
                      <p className="text-body text-stone">{project.location}</p>
                      <p className="mt-2 text-label text-threshold transition-colors duration-fast ease-smooth group-hover:text-paper">
                        VIEW →
                      </p>
                    </div>
                  </Link>
                </FadeUp>
              ))}
            </div>
          </GridWrapper>
        </Section>
      )}

      {/* ── FAQ ── */}
      {(service.faq?.length ?? 0) > 0 && (
        <Section background="surface">
          <GridWrapper>
            <FadeUp>
              <p className="mb-12 text-label text-stone">FREQUENTLY ASKED</p>
            </FadeUp>
            <Accordion
              items={(service.faq || []).map((f) => ({
                question: f.question,
                answer: <PortableText value={f.answer as any} />,
              }))}
            />
          </GridWrapper>
        </Section>
      )}

      {/* ── CTA ── */}
      <Section>
        <GridWrapper>
          <FadeUp>
            <div className="flex flex-col items-start gap-8">
              <TextReveal tag="h2" className="max-w-xl text-display-md text-paper">
                READY TO GET STARTED?
              </TextReveal>
              <GhostButton href="/contact">Discuss Your Project</GhostButton>
            </div>
          </FadeUp>
        </GridWrapper>
      </Section>
    </main>
  );
}

'use client';

import { useLayoutEffect, useRef } from 'react';
import Link from 'next/link';

import { gsap, gsapInit } from '@/lib/animations/gsap';
import { cloudinaryUrl } from '@/lib/cloudinary/transforms';

// ─── Types & Data ─────────────────────────────────────────────────────────────

import type { Project } from '@/lib/sanity/types';

// ─── Component ────────────────────────────────────────────────────────────────

interface SceneProjectsProps {
  projects: Project[];
}

export default function SceneProjects({ projects }: SceneProjectsProps) {
  const containerRef = useRef<HTMLDivElement>(null);
  const stripRef = useRef<HTMLDivElement>(null);
  const headingRef = useRef<HTMLDivElement>(null);
  const imageRefs = useRef<(HTMLImageElement | null)[]>([]);
  const infoPanelRefs = useRef<(HTMLDivElement | null)[]>([]);
  const counterSlotRef = useRef<HTMLDivElement>(null);

  useLayoutEffect(() => {
    gsapInit();

    const container = containerRef.current;
    const strip = stripRef.current;
    if (!container || !strip) return;

    if (window.matchMedia('(prefers-reduced-motion: reduce)').matches) {
      // Card 2 info panel starts opacity:0 via GSAP; reveal it immediately
      if (infoPanelRefs.current[1]) {
        (infoPanelRefs.current[1] as HTMLElement).style.opacity = '1';
        (infoPanelRefs.current[1] as HTMLElement).style.transform = 'none';
      }
      return;
    }

    const ctx = gsap.context(() => {
      // ── Set initial off-screen states before creating the timeline ──────────
      // Card 2 info panel starts hidden and offset downward
      if (infoPanelRefs.current[1]) {
        gsap.set(infoPanelRefs.current[1], { y: 40, opacity: 0 });
      }

      // ── Timeline scrubbed by ScrollTrigger ──────────────────────────────────
      // Duration:1 means all child tween positions are normalised 0–1.
      // The ScrollTrigger scrubs from 0 to 1 over 50 vh of scroll
      // (150 vh container − 100 vh sticky viewport = 50 vh scroll travel).
      const tl = gsap.timeline({
        scrollTrigger: {
          trigger: container,
          start: 'top top',
          end: 'bottom bottom',
          scrub: 1.5,
          invalidateOnRefresh: true,
        },
      });

      // ── Main carousel: strip slides left ──────────────────────────────────
      tl.to(
        strip,
        {
          x: () => -(projects.length - 1) * window.innerWidth,
          ease: 'none',
          duration: 1,
        },
        0,
      );

      // ── "THE WORK" heading fades out quickly as carousel begins ──────────
      tl.to(headingRef.current, { opacity: 0, y: -14, ease: 'none', duration: 0.2 }, 0);

      // ── Parallax: images move at 0.7× the strip speed ────────────────────
      // Images are 130 % wide (left: −15 %) so they always cover their card
      // at the maximum offset of ±15 vw.
      //   Card 1: image drifts +15 vw (lags as card exits left)
      //   Card 2: image starts at −15 vw and returns to 0 (enters slightly slower)
      const parallaxDist = () => window.innerWidth * 0.15;

      const img1 = imageRefs.current[0];
      if (img1) {
        tl.to(img1, { x: parallaxDist, ease: 'none', duration: 1 }, 0);
      }

      const img2 = imageRefs.current[1];
      if (img2) {
        tl.fromTo(
          img2,
          { x: () => -window.innerWidth * 0.15 },
          { x: 0, ease: 'none', duration: 1 },
          0,
        );
      }

      // ── Counter slot: "01" → "02" (translateY flips slot items) ──────────
      // The slot div contains projects.length items each 13 px tall.
      // Translating to −50 % (= −13 px) reveals the second item.
      tl.to(counterSlotRef.current, { yPercent: -50, ease: 'none', duration: 0.2 }, 0.4);

      // ── Info panels: card 1 fades out, card 2 slides in ──────────────────
      const info1 = infoPanelRefs.current[0];
      if (info1) {
        tl.to(info1, { opacity: 0, y: 24, ease: 'none', duration: 0.2 }, 0.35);
      }

      const info2 = infoPanelRefs.current[1];
      if (info2) {
        tl.fromTo(
          info2,
          { y: 40, opacity: 0 },
          { y: 0, opacity: 1, ease: 'none', duration: 0.25 },
          0.65,
        );
      }
    }, container);

    return () => ctx.revert();
  }, [projects.length]);

  if (!projects || projects.length === 0) return null;

  return (
    <div ref={containerRef} style={{ height: '150vh' }}>
      <section className="sticky top-0 h-screen overflow-hidden bg-void">
        {/* ── Section label — fades out as carousel starts ── */}
        <div
          ref={headingRef}
          className="pointer-events-none absolute left-12 top-10 z-20 select-none"
        >
          <p className="text-label tracking-[0.3em] text-stone">THE WORK</p>
        </div>

        {/* ── Project counter — slot machine ── */}
        {/* Clipping wrapper shows one number at a time (text-mono = 13px) */}
        <div className="absolute right-12 top-10 z-20 flex items-baseline gap-2">
          <div className="overflow-hidden" style={{ height: '13px', lineHeight: '13px' }}>
            <div ref={counterSlotRef}>
              {projects.map((_, i) => (
                <div
                  key={i}
                  className="font-mono text-mono leading-none text-paper"
                  style={{ height: '13px' }}
                >
                  {String(i + 1).padStart(2, '0')}
                </div>
              ))}
            </div>
          </div>
          <span className="font-mono text-mono text-stone">
            &thinsp;/&thinsp;{String(projects.length).padStart(2, '0')}
          </span>
        </div>

        {/* ── Carousel strip ── */}
        <div
          ref={stripRef}
          className="flex h-full"
          style={{
            width: `${projects.length * 100}vw`,
            willChange: 'transform',
          }}
        >
          {projects.map((project, i) => (
            <div
              key={project._id}
              className="relative h-full w-screen flex-shrink-0 overflow-hidden"
            >
              {/* Full-bleed image — 130 % wide so parallax shift never exposes edges */}
              <img
                ref={(el) => {
                  imageRefs.current[i] = el;
                }}
                src={cloudinaryUrl(project.heroImageId, { width: 1920 })}
                alt=""
                aria-hidden="true"
                loading="lazy"
                fetchPriority="low"
                width={1920}
                height={1280}
                className="absolute top-0 h-full object-cover"
                style={{
                  width: '130%',
                  left: '-15%',
                  willChange: 'transform',
                }}
              />

              {/* Gradient scrim — heavier at bottom for text legibility */}
              <div
                className="pointer-events-none absolute inset-0"
                style={{
                  background:
                    'linear-gradient(to bottom, rgba(0,0,0,0.25) 0%, rgba(0,0,0,0.1) 40%, rgba(0,0,0,0.55) 100%)',
                }}
              />

              {/* Info panel — slides up 40 px on entry (handled by GSAP) */}
              <div
                ref={(el) => {
                  infoPanelRefs.current[i] = el;
